{"thought": "The e_root gives x^e=c mod prime, but c = m^(e^3) mod prime, so x = m^(e^2) mod prime, not m. I need to take e-th root 3 times. Apply e_root three times.", "action": "python", "code": "import json
from math import gcd
from Crypto.Util.number import long_to_bytes
d=json.load(open('keys.json'))
n1,n2,n3,e,c=d['n1'],d['n2'],d['n3'],d['e'],d['c']
p=gcd(n1,n2); r=n2//p; q=n1//p
def inv(a,m): return pow(a,-1,m)
def e_root(a, prime):
    t=(-inv((prime-1)%e, e))%e
    num=1+(prime-1)*t
    assert num%e==0
    return pow(a, num//e, prime)
res={}
for name,prime in [('p',p),('q',q),('r',r)]:
    x=c%prime
    for _ in range(3):
        x=e_root(x,prime)
    res[name]=x
    print(name, pow(x,e**3,prime)==c%prime, x.bit_length())
N=p*q*r
def crt(res,mods):
    x=0
    for r_,m_ in zip(res,mods):
        Mi=N//m_
        x+=r_*Mi*inv(Mi,m_)
    return x%N
m=crt([res['p'],res['q'],res['r']],[p,q,r])
print(long_to_bytes(m))"}
